mapper.update:
update min30k set update_time = now()

       , name = #{name}


       , open = #{open}


       , high = #{high}


       , low = #{low}


       , `close` = #{close}


       , prev_close = #{prevClose}


       , percent = #{percent}


       , volume = #{volume}


       , amount = #{amount}


       , ma5 = #{ma5}


       , ma10 = #{ma10}


       , ma20 = #{ma20}


       , ma30 = #{ma30}


       , ma60 = #{ma60}


       , ma120 = #{ma120}


       , cross_params = #{crossParams}

where code = #{code} and day = #{day}

mapper.select:
select code, day, name, open, high, low, `close`, prev_close, percent, volume, amount
from min30k
where code = #{code}
order by day desc
limit #{limit}
